// Friendly names for the types generated from the backend (schema.ts).
// schema.ts is generated by `npm run api:types`: never edit it by hand.
import { components } from './schema';

type Schemas = components['schemas'];

/** Every response of the API comes wrapped like this. */
export interface ApiResponse<T> {
  status: 'OK' | 'KO';
  detail: T;
}

